/// Read a JSON array of strings.
fn strings(v: Option<&Value>) -> Vec<String> {
    let mut out = Vec::new();
    if let Some(a) = v.and_then(Value::as_array) {
        for e in a {
            if let Some(s) = e.as_str() {
                out.push(s.to_string());
            }
        }
    }
    out
}

/// Write a JSON array of strings.
fn strings_value(items: &[String]) -> Value {
    let mut out = Vec::new();
    for s in items {
        out.push(Value::Str(s.clone()));
    }
    Value::Array(out)
}

/// Read a JSON array of free-form values.
fn values(v: Option<&Value>) -> Vec<Value> {
    match v.and_then(Value::as_array) {
        Some(a) => a.to_vec(),
        None => Vec::new(),
    }
}

/// Read a JSON object whose values are integers.
fn int_map(v: Option<&Value>) -> BTreeMap<String, i64> {
    let mut out = BTreeMap::new();
    if let Some(Value::Object(m)) = v {
        for (k, val) in m {
            out.insert(k.clone(), val.as_i64().unwrap_or(0));
        }
    }
    out
}

/// Write a JSON object whose values are integers.
fn int_map_value(items: &BTreeMap<String, i64>) -> Value {
    let mut m = BTreeMap::new();
    for (k, v) in items {
        m.insert(k.clone(), Value::Int(*v));
    }
    Value::Object(m)
}

/// Read one message.
fn mail(v: Option<&Value>) -> Mail {
    Mail::from_value(v.unwrap_or(&Value::Null))
}

/// Read a list of messages.
fn mails(v: Option<&Value>) -> Vec<Mail> {
    let mut out = Vec::new();
    if let Some(a) = v.and_then(Value::as_array) {
        for e in a {
            out.push(Mail::from_value(e));
        }
    }
    out
}

/// Write a list of messages.
fn mails_value(items: &[Mail]) -> Value {
    let mut out = Vec::new();
    for m in items {
        out.push(m.to_value());
    }
    Value::Array(out)
}
